"use client";

import { useState, type SubmitEvent } from "react";
import { useRouter } from "next/navigation";
import Icon from "@/components/ui/icon";

// query가 바뀌면 부모에서 key를 바꿔 입력값을 초기화해요.
export default function SearchForm({ query }: { query: string }) {
  const router = useRouter();
  const [searchText, setSearchText] = useState(query);
  const hasQuery = query.length > 0;

  function handleSubmit(event: SubmitEvent<HTMLFormElement>) {
    event.preventDefault();
    const nextQuery = searchText.trim();
    router.push(nextQuery ? `/search?query=${encodeURIComponent(nextQuery)}` : "/search");
  }

  if (!hasQuery) {
    return (
      <section className="w-full max-w-xl text-center">
        <h1 className="mb-7 text-2xl font-extrabold tracking-tight text-gray-950 sm:text-3xl">
          어떤 영화를 찾고 있나요?
        </h1>
        <form
          onSubmit={handleSubmit}
          role="search"
          className="flex w-full items-center gap-3 rounded-xl border-2 border-gray-800 bg-white px-4 py-2 shadow-lg"
        >
          <label className="sr-only" htmlFor="movie-search">검색어</label>
          <Icon name="search" className="shrink-0" />
          <input
            id="movie-search"
            type="search"
            value={searchText}
            onChange={(event) => setSearchText(event.target.value)}
            placeholder="예: 스파이더맨"
            className="min-w-0 flex-1 bg-transparent py-2 text-sm outline-none placeholder:text-gray-400"
          />
          <button type="submit" className="rounded-lg bg-gray-950 px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-gray-800">
            검색
          </button>
        </form>
      </section>
    );
  }

  return (
    <>
      <h1 className="mb-5 text-2xl font-extrabold tracking-tight text-gray-950 sm:text-3xl">영화 검색</h1>
      <form
        onSubmit={handleSubmit}
        role="search"
        className="mb-4 flex items-center gap-3 rounded-lg border border-gray-200 bg-white px-3 py-2 shadow-sm"
      >
        <label className="sr-only" htmlFor="movie-search">검색어</label>
        <Icon name="search" className="shrink-0" />
        <input
          id="movie-search"
          type="search"
          value={searchText}
          onChange={(event) => setSearchText(event.target.value)}
          placeholder="영화 제목 또는 원제 검색"
          className="min-w-0 flex-1 bg-transparent py-2 text-sm outline-none"
        />
        {searchText && (
          <button
            type="button"
            aria-label="검색어 지우기"
            onClick={() => setSearchText("")}
            className="px-1 text-xl text-gray-400 hover:text-gray-700"
          >
            ×
          </button>
        )}
        <button type="submit" className="rounded-lg bg-gray-950 px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-gray-800">
          다시 검색
        </button>
      </form>
    </>
  );
}
